# Expected values generated by test/torch/gen_nn_expected.py (torch 2.15.0).
import torch
import torch.nn as nn
import torch.nn.functional as F

def X(shape: List[int], seed: int, dtype = torch.float64) -> torch.Tensor:
    n = 1
    for s in shape: n *= s
    return ((torch.arange(n, dtype=torch.float64) * 0.37 + float(seed)).sin() * 2.0).reshape(shape).to(dtype)

def close(t: torch.Tensor, exp: List[float], rtol: float) -> bool:
    v = t.detach().contiguous().reshape([-1]).double().tolist()
    if len(v) != len(exp):
        print("len mismatch", len(v), len(exp))
        return False
    scale = 0.0
    for e in exp: scale = max(scale, abs(e))
    for i in range(len(v)):
        if abs(v[i] - exp[i]) > rtol * max(abs(exp[i]), 1e-3 * scale):
            print("mismatch at", i, v[i], exp[i])
            return False
    return True

def closef(a: float, b: float, rtol: float) -> bool:
    return abs(a - b) <= rtol * abs(b)

def run(kind: int) -> nn.Linear:
    torch.manual_seed(0)
    lin = nn.Linear(3, 2).double()
    xin = X([4, 3], 13)
    opt: torch.optim.Optimizer = torch.optim.SGD(lin.parameters(), lr=0.1, momentum=0.9, weight_decay=0.01, nesterov=True)
    if kind == 1:
        opt = torch.optim.Adam(lin.parameters(), lr=0.01, weight_decay=0.1)
    elif kind == 2:
        opt = torch.optim.AdamW(lin.parameters(), lr=0.01, weight_decay=0.1)
    elif kind == 3:
        opt = torch.optim.AdamW(lin.parameters(), lr=0.01, amsgrad=True)
    for _ in range(3):
        opt.zero_grad()
        ((lin(xin) ** 2).mean()).backward()
        opt.step()
    return lin

@test
def test_optimizers():
    assert close(run(0).weight, [-0.00667985458109324, 0.39278856651352545, -0.3094327756547889, -0.26621212381688514, -0.05934203904645557, 0.2989655666863653], 1e-13)  # sgd_w
    assert close(run(1).weight, [0.02515897849148674, 0.33938297735389944, -0.4453707046755719, -0.3949953089340816, -0.19248696762284961, 0.18468086005627693], 1e-13)  # adam_w
    assert close(run(2).weight, [0.025156536413324562, 0.3384732864484297, -0.44400133027405614, -0.39376046695212763, -0.19185486742629682, 0.18419252249822157], 1e-13)  # adamw_w
    assert close(run(3).weight, [0.025175501518837372, 0.33933822351038023, -0.44525367709214414, -0.39487775847287415, -0.19242585975212737, 0.18463889459495747], 1e-13)  # adamw_ams

@test
def test_schedulers():
    opt = torch.optim.SGD([torch.zeros([1]).requires_grad_()], lr=0.1)
    sch = torch.optim.lr_scheduler.CosineAnnealingLR(opt, T_max=5, eta_min=0.001)
    lrs = List[float]()
    for _ in range(12):
        opt.step()
        sch.step()
        lrs.append(opt.param_groups[0]["lr"])
    # CosineAnnealingLR updates recursively through math.cos; glibc and Apple libm
    # differ in the last bit, which accumulates to a few ulp over 12 steps.
    cos_lrs = [0.0905463412215599, 0.06579634122155989, 0.035203658778440096, 0.010453658778440105, 0.001, 0.010453658778440102, 0.035203658778440096, 0.06579634122155989, 0.0905463412215599, 0.09999999999999999, 0.09054634122155993, 0.0657963412215599]
    assert len(lrs) == len(cos_lrs) and all(abs(a - b) <= 1e-15 * abs(b) for a, b in zip(lrs, cos_lrs))  # cos_lrs
    opt2 = torch.optim.SGD([torch.zeros([1]).requires_grad_()], lr=0.1)
    sch2 = torch.optim.lr_scheduler.StepLR(opt2, 3, 0.5)
    lrs = []
    for _ in range(7):
        opt2.step()
        sch2.step()
        lrs.append(opt2.param_groups[0].lr)
    assert lrs == [0.1, 0.1, 0.05, 0.05, 0.05, 0.025, 0.025]  # step_lrs

test_optimizers()
test_schedulers()
